tasks.check:
set -e
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
export PYTHONPATH=$PWD TMPDIR=/tmp
PY=.venv/bin/python
for f in $(git status --porcelain | grep -v '\.venv' | sed 's/^...//'); do
  case "$f" in
    data/stories/continuity-initiative/pacing.yaml|tests/test_recovery_after_choice.py) ;;
    *) echo "WHY: edited file outside ownership: $f"; exit 1;;
  esac
done
git diff --quiet HEAD -- storygame packages tests/test_stall_exit_audit.py tests/test_2c_ledger_guard.py tests/test_canon_journey.py || { echo "WHY: engine or protected tests edited"; exit 1; }
[ -f tests/test_recovery_after_choice.py ] || { echo "WHY: WIP patch not applied"; exit 1; }
grep -q "late_commitment_is_honoured" tests/test_recovery_after_choice.py || { echo "WHY: 2C test not renamed"; exit 1; }
$PY - <<'EOF'
import subprocess, yaml
old = yaml.safe_load(subprocess.run(["git","show","HEAD:data/stories/continuity-initiative/pacing.yaml"],capture_output=True,text=True,check=True).stdout)
new = yaml.safe_load(open("data/stories/continuity-initiative/pacing.yaml"))
def evs(d):
    out = {}
    def walk(x):
        if isinstance(x, dict):
            if "id" in x and "scene_id" in x and ("at_turn" in x or "when" in x): out[x["id"]] = x
            for v in x.values(): walk(v)
        elif isinstance(x, list):
            for v in x: walk(v)
    walk(d); return out
a, b = evs(old), evs(new)
assert set(a) == set(b), "WHY: event ids changed"
changed = sorted(i for i in a if a[i] != b[i])
assert changed == ["inspection_recovery_2a"], f"WHY: exactly inspection_recovery_2a may change, got {changed}"
added = [w for w in b["inspection_recovery_2a"]["when"] if w not in a["inspection_recovery_2a"]["when"]]
assert added == [{"fact_id": "restricted_corridor_access", "equals": False}], f"WHY: bad added conditions {added}"
assert all(w in b["inspection_recovery_2a"]["when"] for w in a["inspection_recovery_2a"]["when"]), "WHY: existing conditions removed"
assert {k: v for k, v in b["inspection_recovery_2a"].items() if k != "when"} == {k: v for k, v in a["inspection_recovery_2a"].items() if k != "when"}, "WHY: other fields changed"
print("data ok")
EOF
cp data/stories/continuity-initiative/pacing.yaml /tmp/pacing.fixed.$$
git show HEAD:data/stories/continuity-initiative/pacing.yaml > data/stories/continuity-initiative/pacing.yaml
if $PY -m pytest -q -n0 -p no:cacheprovider tests/test_recovery_after_choice.py -k "_2a_" > /tmp/mut.log 2>&1; then cp /tmp/pacing.fixed.$$ data/stories/continuity-initiative/pacing.yaml; echo "WHY: the 2A tests PASS without the fix, so they do not prove the flaw"; exit 1; fi
cp /tmp/pacing.fixed.$$ data/stories/continuity-initiative/pacing.yaml
echo "mutation ok (2A tests fail without the fix)"
$PY -m pytest -q -n0 -p no:cacheprovider tests/test_recovery_after_choice.py tests/test_2c_ledger_guard.py tests/test_stall_exit_audit.py tests/test_canon_journey.py tests/test_spine_expected_reveals.py tests/test_incident_engine.py tests/test_incident_loader.py tests/test_incident_pressure.py tests/test_incident_recovery.py tests/test_pacing_handoff.py tests/test_scene_relative_pacing.py tests/test_evidence_gap_journeys.py tests/test_evidence_penalty.py tests/test_markdown_story_package.py $(ls tests/test_2a_*.py tests/test_2b_*.py tests/test_2c_*.py tests/test_3a_*.py 2>/dev/null) > /tmp/r7.log 2>&1 || { tail -40 /tmp/r7.log; echo "WHY: focused suites failed"; exit 1; }
tail -3 /tmp/r7.log
$PY -m ruff format --check . && $PY -m ruff check . || { echo "WHY: ruff"; exit 1; }
OUT=/home/bcorfman/dev/ringer-work/act2-2c-yes
mkdir -p $OUT && git add -A >/dev/null 2>&1 && git diff --cached > $OUT/r7.patch && wc -l $OUT/r7.patch && git diff --cached --stat | tail -5
